    """
    Finds the shortest path in a weighted graph.
    The graph is represented as a dictionary where nodes are keys,
    and the values are lists of tuples, where each tuple is a (neighbor, weight).
    The function returns a tuple with the distance of the shortest path and the path itself as a list of nodes.
    If the target is unreachable, it returns (float("inf"), None).

    :param graph: A dict representing the weighted graph.
    :param source: The starting node of the path.
    :param target: The ending node of the path.
    :return: A tuple (distance, path) where distance is the length of the shortest path and path is the list of nodes on the path.
    """
    import heapq

    def dijkstra(graph, start, end):
        distances = {node: float('inf') for node in graph}
        distances[start] = 0
        queue = [(0, start)]
        previous_nodes = {node: None for node in graph}

        while queue:
            current_distance, current_node = heapq.heappop(queue)

            if current_node == end:
                path = []
                while current_node is not None:
                    path.append(current_node)
                    current_node = previous_nodes[current_node]
                return (distances[end], path[::-1])

            for neighbor, weight in graph[current_node]:
                distance = current_distance + weight

                if distance < distances[neighbor]:
                    distances[neighbor] = distance
                    previous_nodes[neighbor] = current_node
                    heapq.heappush(queue, (distance, neighbor))

        return (float('inf'), None)

    return dijkstra(graph, source, target)

