def shortest_path(graph, source, target):
    # Check if source and target are the same
    if source == target:
        return (0, [source])

    # Bidirectional search
    def bidirectional_search(graph, source, target, seen1, seen2):
        queue1, queue2 = deque([(source, [source])]), deque([(target, [target])])
        seen1[source], seen2[target] = True, True

        while queue1 and queue2:
            # Expand from source towards target
            node1, path1 = queue1.popleft() 
